export const carousel = {
  tsx: '"use client";\n\nimport { useRef } from "react";\nimport { Avatar, Button, Card } from "@loamui/core";\nimport "./carousel.css";\n\nconst testimonials = [\n  {\n    name: "Ada Lovelace",\n    role: "Engineering lead, Analytical Engines",\n    quote:\n      "We shipped a bespoke design system in a week. The primitives did the work; we supplied the vocabulary.",\n  },\n  {\n    name: "Amara Okafor",\n    role: "Product designer, Loom & Ledger",\n    quote:\n      "Dark mode, fluid type and contrast all came for free. I stopped writing overrides on day two.",\n  },\n  {\n    name: "Sam Reed",\n    role: "Founder, Northwind Studio",\n    quote:\n      "Our agent reads the docs and writes components that pass review. That has never happened before.",\n  },\n  {\n    name: "Jane Doe",\n    role: "Accessibility consultant",\n    quote:\n      "Real buttons, real headings, real focus rings. Nothing to fix in the audit, which is the highest praise I have.",\n  },\n];\n\nexport function TestimonialCarousel() {\n  const listRef = useRef<HTMLUListElement>(null);\n\n  const scroll = (direction: -1 | 1) => {\n    const list = listRef.current;\n    if (list) list.scrollBy({ left: direction * list.clientWidth });\n  };\n\n  return (\n    <section className="testimonials" aria-labelledby="testimonials-heading">\n      <h2 id="testimonials-heading">What people say</h2>\n      <ul ref={listRef}>\n        {testimonials.map(({ name, role, quote }) => (\n          <li key={name}>\n            <Card>\n              <blockquote>\n                <p>{quote}</p>\n              </blockquote>\n              <footer>\n                <Avatar name={name} aria-hidden />\n                <p>\n                  <strong>{name}</strong>\n                  <br />\n                  {role}\n                </p>\n              </footer>\n            </Card>\n          </li>\n        ))}\n      </ul>\n      <div className="controls">\n        <Button onClick={() => scroll(-1)}>Previous testimonial</Button>\n        <Button onClick={() => scroll(1)}>Next testimonial</Button>\n      </div>\n    </section>\n  );\n}\n',
  css: "@scope (.testimonials) {\n  :scope {\n    container-type: inline-size;\n    display: block grid;\n    gap: var(--loam-space-lg);\n  }\n\n  h2 {\n    margin: 0;\n  }\n\n  ul {\n    display: block grid;\n    gap: var(--loam-space-lg);\n    grid-auto-columns: min(100%, 22rem);\n    grid-auto-flow: column;\n    list-style: none;\n    margin: 0;\n    overflow-inline: auto;\n    overscroll-behavior-inline: contain;\n\n    /* room for the focus ring and card border inside the scrollport */\n    padding: var(--loam-space-xs);\n    scroll-padding-inline: var(--loam-space-xs);\n    scroll-snap-type: inline mandatory;\n\n    @media (prefers-reduced-motion: no-preference) {\n      scroll-behavior: smooth;\n    }\n  }\n\n  li {\n    display: block grid;\n    scroll-snap-align: start;\n  }\n\n  blockquote {\n    font-size: var(--loam-text-lg);\n    margin: 0 0 var(--loam-space-md);\n\n    p {\n      margin: 0;\n    }\n  }\n\n  footer {\n    align-items: safe center;\n    display: block flex;\n    gap: var(--loam-space-sm);\n\n    p {\n      color: var(--loam-color-fg-muted);\n      font-size: var(--loam-text-sm);\n      margin: 0;\n    }\n\n    strong {\n      color: var(--loam-color-fg-strong);\n    }\n  }\n\n  div.controls {\n    display: block flex;\n    flex-wrap: wrap;\n    gap: var(--loam-space-sm);\n  }\n}\n",
};

export const environments = {
  tsx: 'import { Badge, Button, Card } from "@loamui/core";\nimport "./environments.css";\n\ntype Status = "healthy" | "deploying" | "failed";\n\nconst STATUS_LABEL: Record<Status, string> = {\n  healthy: "Healthy",\n  deploying: "Deploying",\n  failed: "Checks failed",\n};\n\nconst ENVIRONMENTS: ReadonlyArray<{\n  name: string;\n  status: Status;\n  lastDeploy: string;\n  commit: string;\n  url: string;\n  action: string;\n}> = [\n  {\n    name: "Production",\n    status: "healthy",\n    lastDeploy: "Today, 09:12",\n    commit: "a1b2c3d",\n    url: "https://app.example.com",\n    action: "Open logs",\n  },\n  {\n    name: "Staging",\n    status: "deploying",\n    lastDeploy: "Today, 10:40",\n    commit: "e4f5a6b",\n    url: "https://staging.example.com",\n    action: "View deploy",\n  },\n  {\n    name: "Preview",\n    status: "failed",\n    lastDeploy: "Yesterday, 17:05",\n    commit: "c7d8e9f",\n    url: "https://pr-482.example.com",\n    action: "Roll back",\n  },\n];\n\nexport function EnvironmentsOverview() {\n  return (\n    <section className="environments">\n      <h2>Environments</h2>\n      <ul>\n        {ENVIRONMENTS.map((env) => (\n          <li key={env.name}>\n            {/* The status class sets --loam-context on the card root; Badge and Button inside answer it. */}\n            <Card className={`environment ${env.status}`}>\n              <h3>\n                {env.name} <Badge dot>{STATUS_LABEL[env.status]}</Badge>\n              </h3>\n              <dl>\n                <dt>Last deploy</dt>\n                <dd>{env.lastDeploy}</dd>\n                <dt>Commit</dt>\n                <dd>\n                  <code>{env.commit}</code>\n                </dd>\n                <dt>URL</dt>\n                <dd>\n                  <a href={env.url}>{env.url}</a>\n                </dd>\n              </dl>\n              <Button>{env.action}</Button>\n            </Card>\n          </li>\n        ))}\n      </ul>\n    </section>\n  );\n}\n',
  css: "@scope (.environments) {\n  :scope {\n    container-type: inline-size;\n    display: block grid;\n    gap: var(--loam-space-lg);\n  }\n\n  /* Three cards in a row while they fit, one column when they do not (Layout guide). */\n  ul {\n    display: block grid;\n    gap: var(--loam-space-lg);\n    grid-template-columns: repeat(auto-fit, minmax(min(16rem, 100%), 1fr));\n    list-style: none;\n    margin: 0;\n    padding: 0;\n  }\n}\n\n@scope (.environment) {\n  :scope {\n    container-type: inline-size;\n    display: block grid;\n    gap: var(--loam-space-md);\n    grid-template-rows: auto 1fr auto;\n\n    /* Each card declares what it means; Badge and Button inside take the status colour. */\n    &.healthy {\n      --loam-context: success;\n    }\n\n    &.deploying {\n      --loam-context: warning;\n    }\n\n    &.failed {\n      --loam-context: danger;\n    }\n  }\n\n  h3 {\n    align-items: safe center;\n    display: block flex;\n    flex-wrap: wrap;\n    gap: var(--loam-space-sm);\n    justify-content: space-between;\n    margin: 0;\n  }\n\n  dl {\n    display: block grid;\n    gap: var(--loam-space-xs) var(--loam-space-md);\n    grid-template-columns: max-content 1fr;\n    margin: 0;\n  }\n\n  dt {\n    color: var(--loam-color-fg-muted);\n    font-size: var(--loam-text-sm);\n  }\n\n  dd {\n    font-size: var(--loam-text-sm);\n    font-variant-numeric: lining-nums tabular-nums;\n    margin: 0;\n    overflow-wrap: anywhere;\n  }\n}\n",
};

export const menu = {
  tsx: 'import { Badge, Button, Card } from "@loamui/core";\nimport "./menu.css";\n\nconst courses = [\n  {\n    title: "Starter",\n    status: "vegetarian",\n    label: "Vegetarian",\n    dishes: [\n      ["Burrata", "Heritage tomatoes, basil oil, sourdough crumb", "£9.50"],\n      ["Roast beetroot", "Whipped goat\'s curd, hazelnuts, dill", "£8.00"],\n      ["Wild mushroom toast", "Garlic butter, parsley, poached egg", "£8.50"],\n    ],\n  },\n  {\n    title: "Dessert",\n    status: "sold-out",\n    label: "Sold out",\n    dishes: [\n      ["Sticky toffee pudding", "Date sponge, butterscotch, clotted cream", "£7.50"],\n      ["Lemon posset", "Shortbread, raspberries", "£6.50"],\n      ["Chocolate tart", "Salted caramel, crème fraîche", "£7.00"],\n    ],\n  },\n] as const;\n\nexport function RestaurantMenu() {\n  return (\n    <section className="menu">\n      <h2>Menu</h2>\n      {courses.map(({ title, status, label, dishes }) => (\n        <Card key={title} className={`menu-card ${status}`}>\n          <h3>\n            {title} <Badge>{label}</Badge>\n          </h3>\n          <dl>\n            {dishes.map(([name, description, price]) => (\n              <div key={name}>\n                <dt>\n                  {name} <data value={price.slice(1)}>{price}</data>\n                </dt>\n                <dd>{description}</dd>\n              </div>\n            ))}\n          </dl>\n          <Button disabled={status === "sold-out"}>Order {title.toLowerCase()}</Button>\n        </Card>\n      ))}\n    </section>\n  );\n}\n',
  css: "@scope (.menu) {\n  :scope {\n    container-type: inline-size;\n    display: block grid;\n    gap: var(--loam-space-lg);\n    grid-template-columns: repeat(auto-fit, minmax(min(18rem, 100%), 1fr));\n  }\n\n  h2 {\n    grid-column: 1 / -1;\n    margin: 0;\n  }\n}\n\n@scope (.menu-card) {\n  :scope {\n    container-type: inline-size;\n    display: block grid;\n    gap: var(--loam-space-md);\n\n    /* The card's status is a fact about the region: the Badge and the\n       Button inside read it, nothing is passed to them as a prop */\n    &.vegetarian {\n      --loam-context: success;\n    }\n\n    &.sold-out {\n      --loam-context: danger;\n    }\n  }\n\n  h3 {\n    align-items: baseline;\n    display: block flex;\n    flex-wrap: wrap;\n    gap: var(--loam-space-sm);\n    margin: 0;\n  }\n\n  dl {\n    display: block grid;\n    gap: var(--loam-space-sm);\n    margin: 0;\n  }\n\n  dt {\n    display: block flex;\n    font-weight: 600;\n    gap: var(--loam-space-sm);\n    justify-content: space-between;\n  }\n\n  dd {\n    color: var(--loam-color-fg-muted);\n    font-size: var(--loam-text-sm);\n    margin: 0;\n  }\n\n  data {\n    font-variant-numeric: lining-nums tabular-nums;\n  }\n}\n",
};

export const pricing = {
  tsx: 'import { Badge, Button, Card } from "@loamui/core";\nimport "./pricing.css";\n\nconst plans = [\n  {\n    name: "Starter",\n    price: "$0",\n    period: "per month",\n    blurb: "For one person trying things out.",\n    features: ["1 project", "Community support", "Basic analytics"],\n    cta: "Start for free",\n  },\n  {\n    name: "Team",\n    price: "$24",\n    period: "per seat / month",\n    blurb: "For small teams shipping together.",\n    features: ["Unlimited projects", "Priority support", "Shared workspaces", "Audit log"],\n    cta: "Choose Team",\n    recommended: true,\n  },\n  {\n    name: "Enterprise",\n    price: "Custom",\n    period: "billed annually",\n    blurb: "For organisations with their own requirements.",\n    features: ["Everything in Team", "SSO and SCIM", "Dedicated support", "Custom contracts"],\n    cta: "Contact sales",\n  },\n];\n\nexport function PricingSection() {\n  return (\n    <section className="pricing" aria-labelledby="pricing-heading">\n      <h2 id="pricing-heading">Plans and pricing</h2>\n      <p className="lede">Start free, upgrade when the team grows. No card required.</p>\n      <ul className="plans">\n        {plans.map((plan) => (\n          <li key={plan.name}>\n            <Card className={plan.recommended ? "plan recommended" : "plan"}>\n              <div className="head">\n                <h3>{plan.name}</h3>\n                {plan.recommended && <Badge>Recommended</Badge>}\n              </div>\n              <p className="price">\n                {plan.price} <span>{plan.period}</span>\n              </p>\n              <p className="blurb">{plan.blurb}</p>\n              <ul className="features">\n                {plan.features.map((feature) => (\n                  <li key={feature}>{feature}</li>\n                ))}\n              </ul>\n              <Button>{plan.cta}</Button>\n            </Card>\n          </li>\n        ))}\n      </ul>\n    </section>\n  );\n}\n',
  css: "@scope (.pricing) {\n  :scope {\n    container-type: inline-size;\n    display: block grid;\n    gap: var(--loam-space-lg);\n  }\n\n  h2 {\n    margin: 0;\n  }\n\n  p.lede {\n    color: var(--loam-color-fg-muted);\n    font-size: var(--loam-text-lg);\n    margin: 0;\n    max-inline-size: var(--loam-measure);\n  }\n\n  /* three in a row is the parent's grid, not a prop on the card */\n  ul.plans {\n    display: block grid;\n    gap: var(--loam-space-lg);\n    grid-template-columns: repeat(auto-fit, minmax(min(18rem, 100%), 1fr));\n    list-style: none;\n    margin: 0;\n    padding: 0;\n  }\n}\n\n@scope (.plan) {\n  :scope {\n    container-type: inline-size;\n    display: block grid;\n    gap: var(--loam-space-md);\n    grid-template-rows: auto auto auto 1fr auto; /* features take the slack */\n  }\n\n  /* the recommended plan is a primary region: Badge and Button recolour */\n  :scope.recommended {\n    --loam-context: primary;\n  }\n\n  div.head {\n    align-items: safe center;\n    display: block flex;\n    flex-wrap: wrap;\n    gap: var(--loam-space-sm);\n    justify-content: space-between;\n  }\n\n  h3,\n  p,\n  ul.features {\n    margin: 0;\n  }\n\n  p.price {\n    font-size: var(--loam-text-2xl);\n    font-variant-numeric: lining-nums tabular-nums;\n    font-weight: 700;\n  }\n\n  p.price span,\n  p.blurb {\n    color: var(--loam-color-fg-muted);\n    font-size: var(--loam-text-sm);\n    font-weight: 400;\n  }\n\n  ul.features {\n    display: block grid;\n    gap: var(--loam-space-xs);\n  }\n}\n",
};
